class Policy(StrEnum):
    """
    Whether this engine is one we install at all. A property of
    the engine, not of this host.

    * `managed` — we fetch, verify and retain builds of it.
      llama.cpp, which ships prebuilt release assets with
      per-asset digests.
    * `manual` — the operator installs it and we discover what
      they installed. vLLM, whose unit of installation is a
      Python environment: an interpreter of a version we do not
      control (specifically 3.12 for the ROCm and Intel wheels),
      several GB per retained copy, three of six targets on a
      non-default package index, Apple silicon served by a
      separate project entirely, and no single digest that
      verifies the result. Decided 2026-09-09.

    Separate from `installable` because the two answer different
    questions and the UI renders them differently.
    `installable: false` under `policy: managed` means *not on
    this host* — there is a build, just not for this one, which
    is Linux + NVIDIA llama.cpp. `policy: manual` means *not by
    us, anywhere*, and the UI owes the operator instructions
    (`manualInstall`) rather than a disabled install button.
    Inferring that difference from a false boolean would be
    guesswork.

    """

    managed = 'managed'
    manual = 'manual'


class ManualInstall(BaseModel):
    """
    Instructions for installing an engine we do not manage, written
    for the host we actually detected.

    This exists so that "we don't install this one" is still an
    answer the operator can act on. A refusal that names the exact
    command is a different product from a refusal that says no —
    and since a `manual` engine's refusal is permanent rather than
    situational, it is the only surface the operator gets.

    """

    command: str | None = Field(
        None,
        description='A copy-pasteable command for the detected platform and\naccelerator, e.g.\n`uv pip install vllm --torch-backend=auto`. Omitted when we\ncannot name one honestly — an unrecognised accelerator, or a\ntarget upstream serves from a separate project — in which\ncase `docsUrl` and `notes` carry it. Never a guess: a\ncommand that does not work is worse than no command, because\nthe operator will believe it.\n',
    )
    docsUrl: str = Field(
        ...,
        description="Upstream's own install page. Required, and deliberately the\none field that always exists: upstream's instructions are\ncorrect for longer than any copy we make of them, and this\nis the value that stays right when our `command` goes stale.\n",
    )
    notes: str | None = Field(
        None,
        description='Constraints the command alone does not convey — a required\nPython version, a non-default package index, that this\ntarget is served by a separate upstream project, or that the\nplatform is unsupported and the way in is a Linux VM.\n',
    )


class Accelerator(StrEnum):
    """
    `metal` is reported on Apple silicon even though there is no
    separate Metal asset - the plain macOS build has it compiled
    in, and saying `none` there would read as "no GPU".

    `vulkan` is how a non-NVIDIA GPU on **Windows** is served,
    and it exists because until 2026-09-18 there was no answer
    at all: the ROCm probe looked for `rocm-smi` or `/opt/rocm`
    and the SYCL probe for `sycl-ls` or Linux sysfs, none of
    which exists on Windows, so every AMD and Intel card there
    fell through to `none` - a CPU build, a fit scored against
    RAM, and the starter set inverted to the smallest model, on
    a machine built around a graphics card.

    Vulkan rather than ROCm or SYCL for that case because
    upstream publishes `win-vulkan-x64` in every release, it
    needs no vendor SDK, and one build covers AMD and Intel
    alike. `rocm` is still reported on Windows when the HIP SDK
    is actually installed, which is what makes
    `win-rocm-10.0-x64` reachable rather than dead code.

    """

    none = 'none'
    cuda = 'cuda'
    rocm = 'rocm'
    metal = 'metal'
    sycl = 'sycl'
    vulkan = 'vulkan'


class HostAccelerator(BaseModel):
    """
    What the agent detected about this machine, insofar as it
    decides which engine build to fetch. Not a general hardware
    inventory - the VRAM-and-quant-fit surface that M3 needs belongs
    to the library component, not here.

    """

    os: Os | None = None
    arch: Arch | None = None
    accelerator: Accelerator | None = Field(
        None,
        description='`metal` is reported on Apple silicon even though there is no\nseparate Metal asset - the plain macOS build has it compiled\nin, and saying `none` there would read as "no GPU".\n\n`vulkan` is how a non-NVIDIA GPU on **Windows** is served,\nand it exists because until 2026-09-18 there was no answer\nat all: the ROCm probe looked for `rocm-smi` or `/opt/rocm`\nand the SYCL probe for `sycl-ls` or Linux sysfs, none of\nwhich exists on Windows, so every AMD and Intel card there\nfell through to `none` - a CPU build, a fit scored against\nRAM, and the starter set inverted to the smallest model, on\na machine built around a graphics card.\n\nVulkan rather than ROCm or SYCL for that case because\nupstream publishes `win-vulkan-x64` in every release, it\nneeds no vendor SDK, and one build covers AMD and Intel\nalike. `rocm` is still reported on Windows when the HIP SDK\nis actually installed, which is what makes\n`win-rocm-10.0-x64` reachable rather than dead code.\n',
    )
    acceleratorVersion: str | None = Field(
        None,
        description="For CUDA, the highest version the installed driver supports.\nSelection takes the highest published build whose major\nmatches and whose minor is no greater than this. When the\nrelease publishes no such build — upstream moved from 13.3\nto 13.4 on 2026-09-15 and stopped shipping 13.3 — the lowest\npublished minor **above** it within the same major is taken\ninstead, under CUDA's minor-version compatibility (an\napplication built with any 13.x toolkit runs on any 13.x\ndriver, minus PTX JIT for newer PTX and APIs the driver\nlacks; verified live with b10990's 13.4 build on a 13.3\ndriver), and the agent logs the choice. A different major\nis never chosen, and the refusal says so. The candidate\nminors are read from the release's own asset names, not a\ntable: the table this replaced went stale in a day.\n",
    )


class EngineInstallRequest(BaseModel):
    version: str | None = Field(
        None,
        description='A specific upstream build to install. Omit for the newest.\nPresent so an operator who found a regression can pin the\nbuild that worked, which is the whole reason we record the\nversion rather than just "installed".\n',
    )


class State(StrEnum):
    """
    * `resolving` - asking upstream which build and which asset.
    * `downloading` - fetching. On Windows with CUDA this is two
      assets, the binary and a separate CUDA runtime, and the
      byte counters cover both.
    * `verifying` - comparing the SHA-256 the releases API
      reported for the asset. Upstream publishes no checksum
      file; the digest arrives with the asset metadata, so
      there is no excuse for skipping this.
    * `extracting` - unpacking into a new versioned directory.
    * `done` / `failed` / `cancelled` - terminal, and retained
      until the next install starts.

    """

    resolving = 'resolving'
    downloading = 'downloading'
    verifying = 'verifying'
    extracting = 'extracting'
    done = 'done'
    failed = 'failed'
    cancelled = 'cancelled'


class EngineInstall(BaseModel):
    """
    Progress of one install. Phases are named rather than reduced to
    a percentage because they fail differently and the operator
    needs to know which one they are in: a stall in `downloading` is
    the network, a stall in `extracting` is the disk, and a failure
    in `verifying` is the one that means do not run this.

    """

    engine: EngineKind
    state: State = Field(
        ...,
        description='* `resolving` - asking upstream which build and which asset.\n* `downloading` - fetching. On Windows with CUDA this is two\n  assets, the binary and a separate CUDA runtime, and the\n  byte counters cover both.\n* `verifying` - comparing the SHA-256 the releases API\n  reported for the asset. Upstream publishes no checksum\n  file; the digest arrives with the asset metadata, so\n  there is no excuse for skipping this.\n* `extracting` - unpacking into a new versioned directory.\n* `done` / `failed` / `cancelled` - terminal, and retained\n  until the next install starts.\n',
    )
    version: str | None = Field(
        None, description='The build being installed, once resolved.'
    )
    variant: str | None = None
    bytesDownloaded: int | None = None
    bytesTotal: int | None = Field(
        None,
        description='Total across every asset this install needs. Absent until\n`resolving` finishes.\n',
    )
    message: str | None = Field(
        None, description='What is happening now, for a status line.'
    )
    error: str | None = Field(None, description='Populated when `state: failed`.')
    startedAt: AwareDatetime | None = None
    finishedAt: AwareDatetime | None = None


class Origin(StrEnum):
    """
    Where the binary came from. Discovery precedence is an
    explicit `binary` on the runtime, then `configured`, then
    `managed`, then `PATH`.

    * `managed` — fetched and verified by us. Only ever set for
      an engine with `acquisition.policy: managed`.
    * `configured` — an explicit path the operator set. Two
      sources: a `binary` on one runtime, for someone who builds
      llama.cpp themselves or wants a specific build for one
      model; or an install-wide path in the agent's own
      config, which is how an engine we never manage becomes
      discoverable at all. Without the second, an operator with
      a perfectly good vLLM venv would read as unavailable
      unless they put it on `PATH` or repeated the path on every
      runtime.
    * `path` — found on `PATH`.

    """

    managed = 'managed'
    configured = 'configured'
    path = 'path'


class FrameworkAccelerator(StrEnum):
    """
    What a Python engine's installed framework was *built for*, read
    from its build tag rather than from the host.

    Deliberately a separate schema from `HostAccelerator.accelerator`
    rather than a shared one, because the two say different things
    and carry different values. That one reports what the *machine*
    has; this one reports what the *wheel* has. A CUDA box running a
    CPU-only PyTorch is a real and quiet failure — everything looks
    installed and inference is orders of magnitude slower — and it
    is visible only as the disagreement between these two fields.

    `unknown` when the build tag does not parse. Honest, and better
    than reporting `none`, which would read as a definite claim that
    there is no acceleration.

    """

    none = 'none'
    cuda = 'cuda'
    rocm = 'rocm'
    xpu = 'xpu'
    metal = 'metal'
    unknown = 'unknown'


class RuntimeSpec(BaseModel):
    """
    Declarative half of a Runtime — what the operator asked for.
    Used for create and update bodies; observed fields are
    server-owned and excluded.

    Note what is *not* here: a command line. The operator declares
    intent (this engine, this model, these flags) and the adapter
    builds the argv. Letting a topology entry carry raw argv would
    make every engine "supported" while making none of them
    knowable — no readiness probe, no flag validation, no version
    story. The resolved argv is reported back on `Runtime.argv` for
    debugging, which is the half of raw-argv access that is
    genuinely useful.

    """

    name: str = Field(
        ...,
        description='Operator-supplied label, unique per node. Referenced by\nan inference-driver on that node to say which runtime it\nfronts. Different nodes may use the same label; install-wide\nruntime identity is the pair (node, name).\n',
        min_length=1,
    )
    engine: EngineKind
    modelPath: str = Field(
        ...,
        description="Absolute path to the model on this host — a `.gguf` file, or\na directory for multi-file formats. **The operator's own\npath, in the operator's own layout.** We never relocate,\nrename, or hash-address a model file; a runtime points at\nwhere the user put it.\n\nFor a sharded GGUF this is the *first* shard\n(`…-00001-of-0000N.gguf`), which is what the engine expects.\nWhen a runtime is created from the library, this is the\n`path` off a `LibraryModel` and the `flags` are a\n`ModelProfile` — but nothing here depends on the library\nexisting, and a hand-written runtime is still a runtime.\n\n**When the library is on another host, this is still the\nlibrary's spelling** (M11). The node resolves where the same\nfile is on its own disk through the Library folder's\n`mounts` and its own `pathMappings` overrides, at every\nspawn and never onto this field — so the declaration keeps\nlinking to its library entry (`GET /v1/models?path=` is keyed\nto the library's own path), and a changed mapping takes\neffect at the next start with nothing re-declared. What was\nactually opened is reported as `Runtime.localPath`.\n",
    )
    modelAlias: str | None = Field(
        None,
        description="The model id this runtime serves under, and therefore what a\nclient asks the gateway for. Defaults to the model\nfilename with its extension stripped — plainly-named files\nmean the obvious name is already the right one, so this is\nan override, not a requirement.\n\n**The resolved value is always passed to the engine\nexplicitly, never left to the engine's own default.** vLLM's\ndefault served name is the `--model` argument verbatim, and\nwe launch models by absolute path because the user's files\nstay theirs — so leaving it unset would publish\n`/home/you/models/Qwen3-8B` as an OpenAI model id. That\nleaks the operator's directory layout to every API client\nand, worse, makes the routing key differ per host for the\nsame model, which breaks both multi-host placement and any\nfailover priority list that names a model. llama.cpp derives\nits default from the filename and would have been fine,\nwhich is exactly why this was invisible until a second\nengine existed.\n",
    )
    host: str | None = Field(
        '127.0.0.1',
        description="Address the engine binds. Defaults to loopback: an engine\nhas no auth of its own, so it must not be exposed directly.\nReaching a model from another machine is the gateway's job,\nand the gateway has auth.\n",
    )
    port: int | None = Field(
        None,
        description='Port the engine binds. Assigned from an ephemeral range when\nomitted — with N runtimes the operator should not have to\nhand out port numbers.\n',
        ge=1,
        le=65535,
    )
    autoStart: bool | None = Field(
        True,
        description='Whether the agent spawns this runtime at startup and\nrespawns it on exit. False leaves it declared but\n`stopped`, which is how a rarely-used large model stays\nconfigured without holding VRAM.\n',
    )
    autoDriver: bool | None = Field(
        True,
        description='Whether the agent declares and supervises a companion\n`inference-driver` that follows this runtime by name, so\nthe model is routable the moment the engine is ready. The\ncompanion is `<name>-driver`; `Runtime.driver` reports it.\nSet false to front the runtime by hand — one hand-tuned\ndriver pointed at an engine is still a supported shape, it\nis just no longer the only one. Decided 2026-09-10 over a\ndeclared pool: one driver per backend is the rule the\ncontract has stated since M0, a runtime is a backend, and a\npool would need allocation state and give drivers names\nthat mean a different model every hour.\n',
    )
    idleUnloadSeconds: int | None = Field(
        None,
        description="Stop the engine after this many seconds with no request for\nits model through the gateway, releasing its GPU memory.\nAbsent or 0 means never, which is every existing\ndeclaration's behaviour unchanged.\n\n**The gateway decides; this agent executes.** Only the\ngateway sees demand, so it tracks the last request per\nruntime and calls `POST .../stop` with `reason: idle` when\nthis expires. A runtime with a request in flight is never\nstopped. Setting this also **opts the runtime into\neviction**: when a `startOnDemand` model will not fit, the\ngateway may stop the most-idle runtimes that carry a timeout\nto make room. A model that must stay resident sets none.\n",
        ge=0,
    )
    startOnDemand: bool | None = Field(
        False,
        description="Start this runtime when a request arrives for its model and\nit is `stopped`. The gateway calls `POST .../start`, waits\nfor `ready` (bounded by its `swapWaitSeconds`), and serves\nthe request; the response says it did (`swapped_in`). With\n`autoStart: false` and `idleUnloadSeconds` set, this is\nllama-swap's model: declare five, load none, serve whichever\nis asked for, unload it when it goes quiet — several at\nonce when they fit.\n\nFalse by default so that a hand-pressed Stop stays stopped.\n",
    )
    flags: dict[str, Any] | None = Field(
        None,
        description='Curated engine flags, keyed by the field names in the\nadapter\'s `flagSchema`. Validated on write: an unknown key\nis a 400, never a silent drop.\n\nThis is the per-model settings surface — the reason\n"tweaking llama.cpp settings for every different model" is a\ncomplaint we answer. Values here are engine *launch* flags;\nsampling parameters that ride on each request are the\ngateway\'s, not these.\n',
    )
    extraArgs: list[str] | None = Field(
        None,
        description='Verbatim extra arguments, appended after everything the\nadapter generated. The escape hatch for the long tail of\nflags a curated surface will always miss.\n\nUnvalidated by definition, so the UI must present it as the\nadvanced option it is: a bad value here surfaces as an\nengine that refuses to start, and the resolved `argv` plus\nthe captured engine output are how it gets diagnosed.\n',
    )
    env: dict[str, str] | None = Field(
        None,
        description='Extra environment variables for the engine process. Needed\nmore often than for a component — accelerator selection\n(`CUDA_VISIBLE_DEVICES`, `HIP_VISIBLE_DEVICES`) is how a\nruntime is pinned to one GPU, which is what makes two\nreplicas on two cards possible.\n',
    )
    workingDirectory: str | None = Field(
        None,
        description="Working directory for the engine process. Defaults to the\nbinary's own directory, which is what prebuilt llama.cpp\nreleases need to find their bundled shared libraries.\n",
    )
    binary: str | None = Field(
        None,
        description='Override the binary for this one runtime, ignoring whatever\nthe adapter discovered. For running one model on a custom\nbuild without disturbing the rest of the install.\n',
    )


class Source(StrEnum):
    """
    Which counter answered. On the wire so that "this host cannot
    measure it" stays distinguishable from "this engine is not
    reading" — both of which make the field absent, and only one
    of which is worth reporting to whoever runs the host.

    """

    windows_io_counters = 'windows_io_counters'
    proc_io_rchar = 'proc_io_rchar'
    rusage_diskio = 'rusage_diskio'


class LoadProgress(BaseModel):
    """
    How far into reading its model an engine is, **present only while
    that is a thing anyone can honestly say**.

    A large model on shared storage takes minutes to load, and for
    those minutes a healthy node and a hung one look identical: the
    status is `loading`, the engine answers 503, and nothing says
    whether bytes are moving. This is what distinguishes them.

    **Absent is the normal case, not an error.** It is absent
    whenever the read cannot be observed:

      * the engine **memory-maps** its model, which llama.cpp does by
        default — faulted pages are not read I/O, so the counter sees
        a few megabytes of header and then nothing. Measured
        2026-09-17 on Windows: 268 MB touched through a mapping moved
        `ReadTransferCount` by 0.0 MB, against +268.4 MB for the same
        bytes read normally, over SMB and on local disk alike;
      * the host has no counter this agent knows;
      * the runtime is not loading, or has no process.

    So a consumer renders a bar when this is present and elapsed time
    when it is not, and never infers one from the other. A field that
    was always present would force every consumer to invent the
    distinction, and one of them would get it wrong by showing a bar
    frozen at 0.1% for four minutes — which is the question this
    answers, made worse by looking authoritative.

    """

    bytesRead: int = Field(
        ...,
        description='Bytes this engine process has read since it started. Includes\nwhatever else it read — its own binary, CUDA libraries — which\nis noise against a model measured in gigabytes.\n',
    )
    totalBytes: int | None = Field(
        None,
        description="Size of the model file this runtime is opening, when it could\nbe measured. Null when the path could not be stat'd, which is\na share that has gone away — exactly when a load is worth\nwatching, so progress is still reported without a percentage.\n",
    )
    bytesPerSecond: float | None = Field(
        None,
        description='Observed over a short window, so it tracks a share that has\njust got slower rather than averaging the whole load. Null on\nthe first pair of readings.\n',
    )
    source: Source = Field(
        ...,
        description='Which counter answered. On the wire so that "this host cannot\nmeasure it" stays distinguishable from "this engine is not\nreading" — both of which make the field absent, and only one\nof which is worth reporting to whoever runs the host.\n',
    )


class CopyProgress(BaseModel):
    """
    How far into copying a model file to this node's own disk the
    agent is (`docs/design/node-local-model-copy.md`). Present
    exactly while `status` is `copying`, and absent otherwise.

    **The same shape as `LoadProgress` and deliberately not the same
    field**, because the two differ on the question that field
    exists to answer. `loadProgress` is absent whenever the bytes
    cannot be observed — llama.cpp maps its model and faulted pages
    are not read I/O — so a consumer reads *absent* as "show elapsed
    instead". Here the agent is the process doing the reading and
    the writing, so the bytes are never unobservable and absent can
    only mean "no copy is running". One field carrying both meanings
    would make every consumer invent the distinction, and this
    project has already paid for that once.

    It reports the copy of ONE model file — the file this runtime
    points at. Several runtimes over one file (M6 replicas) copy it
    once, so the second and third report the same copy while it runs
    and none of them afterwards.

    """

    bytesCopied: int = Field(
        ..., description='Bytes written to the destination so far.'
    )
    totalBytes: int | None = Field(
        None,
        description="Size of the source file, when it could be measured. Null\nwhen the source could not be stat'd — a share that has gone\naway mid-copy, which is exactly when this is worth watching,\nso progress is still reported without a percentage.\n",
    )
    bytesPerSecond: float | None = Field(
        None,
        description='Observed over a short window rather than averaged over the\nwhole copy, so a share that has just got slower shows it.\nNull on the first pair of readings.\n',
    )
    destination: str | None = Field(
        None,
        description='Where the copy is being written, on this host. Reported\nbecause the operator picked the directory and the commonest\nquestion about a long copy is which disk is filling up.\n\nThis is the **final** path, not the temporary name the bytes\nare actually landing in: a partial copy never carries the\nname an engine would open (§3.3 of the design), and naming\nthe temp file here would invite someone to go looking for a\nfile that exists only until the rename.\n',
    )


class ModelCopySkipped(BaseModel):
    path: str
    runtime: str | None = Field(
        None, description='The runtime holding it open, when that is why.'
    )
    reason: str = Field(
        ...,
        description='Plain-language reason this copy is still on disk — in use by\na running runtime, permission denied, or the delete failed.\nRendered as written; the UI does not classify it.\n',
    )


class RuntimeLocalPathSource(StrEnum):
    """
    Which rule decided this runtime's `localPath`.

    The three values of `FolderReachSource`, plus `copy`. They are a
    separate enum rather than a shared one because a *folder* can
    never be a copy — a copy is made per model file, and putting
    `copy` in the folder enum would hand the Library's Folders page
    a value it can never receive and must still handle.

    * `same_path` — no rule applied; `modelPath` is opened as
      written. Every single-host install.
    * `inherited` — the Library folder's own `mounts` carried an
      entry of this host's OS shape.
    * `override` — this node's `pathMappings` named the folder.
    * `copy` — this node holds its own valid copy of the file and is
      opening that. Resolved ahead of the other three, which is why
      it can appear on a node that also has a mount: the mount is
      how the copy got here.

    """

    same_path = 'same_path'
    inherited = 'inherited'
    override = 'override'
    copy = 'copy'


class RuntimeStatus(StrEnum):
    """
    Operational state of an engine process. Distinct from
    `ComponentStatus`: an engine has no safe mode (nothing to
    recover a config from), and it has a model-load phase that a
    component does not.

    These are defined by what they *mean*, not by how any one engine
    reports them. That distinction is load-bearing, because the two
    engines report the load phase in opposite ways — see `loading`.

    * `copying` — this node is making its local copy of the model
      file, and **nothing has been spawned yet**
      (`docs/design/node-local-model-copy.md`). It is its own state
      rather than `starting` for the reason the list above is
      defined by meaning: `starting` says *spawned, and we have no
      information yet*, and there is no process here at all. Folding
      it in would put a multi-minute wait behind a word that
      promises a process — the same "healthy and broken look
      identical" window this feature exists to close. `copyProgress`
      says how far along, and unlike `loadProgress` it is always
      present in this state, because the agent is the one moving the
      bytes. Only reachable on a node with `modelCopyEnabled`; a
      copy that is skipped or already valid never enters it.
    * `starting` — spawned, and we have no information yet. Not "the
      probe failed": the honest gap between spawning a process and
      learning anything about it.
    * `loading` — the engine is alive and working, and is not
      servable yet. Worth its own state rather than folding into
      `starting`: a large quant off a spinning disk can sit here for
      minutes, and an operator staring at a dashboard needs to know
      the difference between "working on it" and "wedged".

      How it is *observed* is per-engine, and this is most of why
      readiness is per-adapter rather than a shared TCP check.
      `llama-server` says so itself, answering `/health` with 503
      and a loading status. **vLLM does the opposite:** it binds its
      port before loading the model and does not answer at all until
      the model is in memory, so for minutes it is
      indistinguishable — over the network alone — from a process
      that died.

      Hence the rule: for an engine that does not answer while
      loading, *the process being alive while nothing answers* **is**
      `loading`. There is nothing else it could be. That inference
      needs the process handle, which the supervisor has and a
      network probe does not, and it is why lifecycle adapters live
      here rather than in the driver. An engine like that also needs
      a per-adapter startup budget to keep "working on it" separable
      from "wedged"; vLLM's is minutes, because CUDA graph capture
      and compilation dominate it.
    * `ready` — model loaded and serving. The only state in which
      the gateway will route to it.
    * `stopped` — deliberately stopped, or declared with
      `autoStart: false`. Not an error; the respawn loop is
      suppressed.
    * `exited` — exited cleanly and is being respawned (transient).
    * `crashed` — could not be launched, or exited non-zero. If this
      process never became ready, automatic retries stop immediately
      rather than repeating a failed model load. After readiness,
      unexpected non-zero exits retry with back-off up to five
      consecutive crashes; 60 seconds of continuously observed ready
      time resets that history. Loading time does not count as useful
      uptime. `lastError` and the captured engine output say why;
      `POST .../restart` retries after settings have been corrected.

    """

    copying = 'copying'
    starting = 'starting'
    loading = 'loading'
    ready = 'ready'
    stopped = 'stopped'
    exited = 'exited'
    crashed = 'crashed'


class RuntimeCapabilities(BaseModel):
    """
    What the running engine reports about itself, read back after it
    becomes ready rather than inferred from the declaration. The
    gateway keys routing decisions off these; the UI displays them.

    """

    contextLength: int | None = Field(
        None,
        description='Effective context window of the loaded model, as the engine\nresolved it — which is not necessarily what was asked for.\nA requested context larger than the model or the available\nmemory gets clamped by the engine, and the clamped value is\nthe true one.\n',
        ge=0,
    )
    parallelSlots: int | None = Field(
        None,
        description='Concurrent requests this runtime can serve. The unit of\ncapacity the gateway divides work across, so a single\nruntime with several slots and several runtimes with one\neach are the same kind of thing to the layer above.\n',
        ge=1,
    )
    embeddings: bool | None = Field(
        None, description='Whether this runtime was started in embedding mode.'
    )
    vision: bool | None = Field(
        None, description='Whether the loaded runtime explicitly reports image input.'
    )
    multimodal: bool | None = Field(
        None, description='Whether a projector was loaded alongside the model.'
    )


class StopReason(StrEnum):
    """
    * `operator` — an explicit stop, from the UI or the API.
    * `idle` — the gateway unloaded it after `idleUnloadSeconds`
      passed with no request for its model. It comes back on the
      next request if `startOnDemand` is set.
    * `autoStart` — declared with `autoStart: false` and never
      started in this agent's lifetime.

    A reason beside `status: stopped` rather than three new members
    of `RuntimeStatus`, because the state is the same state — the
    process is not running and the respawn loop is suppressed — and
    only the cause differs.

    """

    operator = 'operator'
    idle = 'idle'
    autoStart = 'autoStart'


class AdmissionDecision(StrEnum):
    """
    Refuse, never queue (decided 2026-09-10). A refusal carries its
    numbers and is overridable with `force`; the on-demand path is
    how a model that does not fit right now gets loaded when it is
    actually asked for.

    """

    admit = 'admit'
    refuse = 'refuse'


class AdmissionFit(StrEnum):
    """
    The same four words the library's guidance uses, plus `unknown`,
    mapped onto a decision by what the spec asked for. `fits` admits.
    `tight` — inside total memory but not free memory — and `split`
    — needs host memory too — refuse a full-offload launch and admit
    one whose `gpuLayers` is set below full, because then the
    operator chose partial offload. `no` refuses. `unknown` admits
    with a warning: a verdict from a budget that could not be
    measured is worse than none.

    """

    fits = 'fits'
    tight = 'tight'
    split = 'split'
    no = 'no'
    unknown = 'unknown'


class AdmissionBasis(StrEnum):
    """
    * `metadata` — the library computed required bytes from the
      model's real metadata at the requested context. Present when
      a `library` component is in this agent's topology and
      answered.
    * `file_size` — the model file's size plus a fixed allowance.
      What an agent with no library reachable can measure on its
      own, said out loud rather than dressed up.

    """

    metadata = 'metadata'
    file_size = 'file_size'


class AdmissionBlocker(BaseModel):
    name: str = Field(..., description='A runtime holding memory on the device.')
    status: RuntimeStatus | None = None
    idleUnloadSeconds: int | None = Field(
        None,
        description='Its declared idle timeout, when it has one. Only a runtime\nwith one is ever evicted by the gateway; the rest are here\nso the operator knows what is holding the memory.\n',
    )
    evictable: bool | None = Field(
        None,
        description='Whether the gateway may stop this runtime to make room —\ntrue exactly when it declared `idleUnloadSeconds`.\n',
    )


class ModelLocation(BaseModel):
    """
    Where a declared model path lands on this host (M11).

    The library describes a model by its path on the library's own
    host; a node that runs the engine elsewhere reaches the same
    file through a `pathMappings` rule, or not at all. This is the
    resolution, reported with the declaration so an operator sees
    both spellings — and reported on the admission dry run so the
    launch screen can say what will happen before the button is
    pressed.

    """

    path: str = Field(..., description="The path as declared — the library's spelling.")
    localPath: str = Field(
        ...,
        description='The path this host would open: `path` through the rule in\n`mapping`, or `path` itself when none applied.\n',
    )
    exists: bool = Field(
        ...,
        description='Whether `localPath` names a file or directory on this host,\nat the moment of measurement. False is what turns the\ndecision to `refuse`.\n',
    )
    mapping: PathMapping | None = Field(
        None, description='The rule that applied, when one did.'
    )
    sizeBytes: int | None = Field(
        None,
        description='Bytes at `localPath` on this host — one file, or every file\nunder a directory. Absent when it does not exist or could\nnot be measured.\n',
        ge=0,
    )
    librarySizeBytes: int | None = Field(
        None,
        description='What the library says the same thing is: its weights file\nfor a file path, its whole `sizeBytes` for a directory.\nAbsent when no library answered.\n',
        ge=0,
    )
    sizeMatchesLibrary: bool | None = Field(
        None,
        description='Whether the two sizes agree. Absent when either is absent.\nFalse is a warning and not a refusal: a stale library scan\nafter an upstream replacement is likelier than a mapping\nthat points at a look-alike, and the engine will say if the\nfile is broken. What this cannot catch, and does not\npretend to, is a different file of the same size.\n',
    )


class LibraryFolderCheckRequest(BaseModel):
    """
    Optional overrides for `POST /v1/library/folders/check`. Same
    idea as `ConfigTestRequest`: what is sent stands in for the
    saved value for this answer only.

    """

    pathMappings: list[PathMapping] | None = Field(
        None,
        description="This node's overrides as they would be after an unsaved\nedit. Absent means the saved ones.\n",
    )


class FolderReachSource(StrEnum):
    """
    Which rule decided a folder's `localPath` on this host.

    * `same_path` — no rule applied; the folder's own path is
      opened as written. Every single-host install, and any node
      that mounts the share at the same path the library uses.
    * `inherited` — the folder's `mounts` carried an entry of this
      host's OS shape. Stated once on the Library, nothing on this
      node.
    * `override` — this node's `pathMappings` named the folder, and
      won.

    """

    same_path = 'same_path'
    inherited = 'inherited'
    override = 'override'


